import React, { useEffect, useState } from 'react';
import { getBookings, getParkingSpots, getParkingSlots, getWallets, getTransactions } from '../services/api';
import { useAuth } from '../context/AuthContext';

const statusColor = (s) => {
  if (!s) return 'neutral';
  const sl = s.toLowerCase();
  if (sl.includes('confirm') || sl.includes('complete')) return 'success';
  if (sl.includes('pending') || sl.includes('hold')) return 'warning';
  if (sl.includes('cancel')) return 'danger';
  return 'neutral';
};

const formatDateTime = (isoString) => {
  if (!isoString) return '--';
  try {
    let str = isoString;
    if (!str.includes('Z') && !str.includes('+') && !str.slice(10).includes('-')) str = str + '+05:30';
    const d = new Date(str);
    return d.toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: true, timeZone: 'Asia/Kolkata' });
  } catch { return '--'; }
};

export default function LenderBookings() {
  const { currentUser } = useAuth();
  const [bookings, setBookings] = useState([]);
  const [mySpots, setMySpots] = useState([]);
  const [earningsMap, setEarningsMap] = useState({}); // bookingId → credited amount
  const [loading, setLoading] = useState(true);
  const [walletBalance, setWalletBalance] = useState(null);

  useEffect(() => {
    const load = async () => {
      try {
        const [allBookings, spots, slots, wallets, allTxns] = await Promise.all([
          getBookings(), getParkingSpots(), getParkingSlots(), getWallets(), getTransactions()
        ]);

        const mySpotList = spots.filter(s => s.user?.userId === currentUser.userId);
        setMySpots(mySpotList);
        const mySpotIds = mySpotList.map(s => s.spotId);
        const mySlotIds = slots.filter(sl => mySpotIds.includes(sl.spot?.spotId)).map(sl => sl.slotId);
        const lenderBookings = allBookings.filter(b => mySlotIds.includes(b.slot?.slotId));
        setBookings(lenderBookings);

        // Find my wallet and its transactions
        const myWallet = wallets.find(w => w.user?.userId === currentUser.userId);
        if (myWallet) {
          setWalletBalance(parseFloat(myWallet.balance || 0));
          // Map bookingId → earning amount from SLOT_EARNING transactions
          const myEarningTxns = allTxns.filter(t => t.wallet?.walletId === myWallet.walletId && t.purpose === 'SLOT_EARNING');
          const eMap = {};
          myEarningTxns.forEach(t => {
            if (t.booking?.bookingId) eMap[t.booking.bookingId] = parseFloat(t.amount || 0);
          });
          setEarningsMap(eMap);
        }
      } catch {}
      setLoading(false);
    };
    load();
  }, [currentUser]);

  if (loading) return <div style={{ padding: 40 }}><div className="loader" /></div>;

  // Summary stats
  const totalEarned = Object.values(earningsMap).reduce((s, v) => s + v, 0);
  const confirmedBookings = bookings.filter(b => b.bookingStatus === 'CONFIRMED' || b.bookingStatus === 'COMPLETED');
  const thisMonthEarned = Object.entries(earningsMap).reduce((sum, [, amt]) => sum + amt, 0); // simplified

  return (
    <div style={{ padding: '32px', maxWidth: '1200px', margin: '0 auto' }}>
      <div className="page-header">
        <h1>Bookings for My Spots</h1>
        <p>{bookings.length} total bookings across {mySpots.length} spot{mySpots.length !== 1 ? 's' : ''}</p>
      </div>

      {/* Money flow banner */}
      <div style={{ background: 'linear-gradient(135deg, #f0fdf4, #dcfce7)', border: '1px solid #86efac', borderRadius: '16px', padding: '20px 24px', marginBottom: '28px', display: 'flex', alignItems: 'center', gap: '20px', flexWrap: 'wrap' }}>
        <div style={{ fontSize: '32px' }}>💸</div>
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 700, color: '#065f46', fontSize: '15px', marginBottom: '4px' }}>How your earnings work</div>
          <div style={{ color: '#166534', fontSize: '13px' }}>
            When a user books your spot → <strong>you receive 90%</strong> of the booking amount directly into your wallet. The platform takes 10% as commission. Every confirmed booking below earns you money automatically.
          </div>
        </div>
        {walletBalance !== null && (
          <div style={{ background: '#fff', borderRadius: '12px', padding: '12px 20px', textAlign: 'center', border: '1px solid #bbf7d0', minWidth: '140px' }}>
            <div style={{ fontSize: '11px', color: '#166534', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.5px', marginBottom: '4px' }}>Wallet Balance</div>
            <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, color: '#15803d', fontSize: '1.5rem' }}>₹{walletBalance.toFixed(2)}</div>
          </div>
        )}
      </div>

      {/* Stats row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px', marginBottom: '28px' }}>
        {[
          { label: 'Total Bookings', value: bookings.length, icon: '📋', color: '#4f46e5', bg: '#ede9fe', border: '#c4b5fd' },
          { label: 'Confirmed', value: confirmedBookings.length, icon: '✅', color: '#059669', bg: '#d1fae5', border: '#6ee7b7' },
          { label: 'Total Earned', value: `₹${totalEarned.toFixed(2)}`, icon: '💰', color: '#b45309', bg: '#fef3c7', border: '#fde68a' },
          { label: 'Your Cut', value: '90%', icon: '🏦', color: '#0369a1', bg: '#e0f2fe', border: '#7dd3fc' },
        ].map(s => (
          <div key={s.label} style={{ background: s.bg, border: `1px solid ${s.border}`, borderRadius: '14px', padding: '16px 18px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
              <div style={{ fontSize: '11px', color: s.color, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.5px' }}>{s.label}</div>
              <span style={{ fontSize: '18px' }}>{s.icon}</span>
            </div>
            <div style={{ fontFamily: 'var(--font-display)', fontWeight: 800, color: s.color, fontSize: '1.5rem' }}>{s.value}</div>
          </div>
        ))}
      </div>

      {bookings.length === 0 ? (
        <div className="empty-state"><div className="icon">📋</div><p>No bookings on your spots yet.</p></div>
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>Booking Code</th>
                <th>Spot / Slot</th>
                <th>User</th>
                <th>Vehicle</th>
                <th>Date & Time</th>
                <th>Booking Amt</th>
                <th>Your Earning (90%)</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map(b => {
                const bookingAmt = parseFloat(b.finalAmt || b.estimatedAmt || 0);
                const myEarning = earningsMap[b.bookingId] ?? (bookingAmt * 0.9);
                const spotForBooking = mySpots.find(sp => {
                  // we don't have direct spot on booking, but we can infer from slot
                  return true; // simplified — show first spot name if needed
                });
                const slotLabel = b.slot?.slotNo ? `Slot #${b.slot.slotNo}` : '—';

                return (
                  <tr key={b.bookingId}>
                    <td style={{ fontFamily: 'monospace', color: 'var(--accent)', fontWeight: 700 }}>{b.bookingCode || `#${b.bookingId}`}</td>
                    <td style={{ fontSize: '12px', color: 'var(--text2)' }}>{slotLabel}</td>
                    <td style={{ color: 'var(--text)' }}>{b.user?.name || `User #${b.user?.userId}`}</td>
                    <td style={{ fontFamily: 'monospace', fontSize: '12px' }}>{b.vehicle?.vehicleNo || '—'}</td>
                    <td style={{ fontSize: '11px', color: 'var(--text2)' }}>{formatDateTime(b.startTime)}</td>
                    <td style={{ color: 'var(--text2)', fontWeight: 600 }}>₹{bookingAmt.toFixed(2)}</td>
                    <td>
                      {(b.bookingStatus === 'CONFIRMED' || b.bookingStatus === 'COMPLETED') ? (
                        <span style={{ fontFamily: 'var(--font-display)', fontWeight: 800, color: '#059669', fontSize: '14px' }}>
                          +₹{myEarning.toFixed(2)}
                        </span>
                      ) : (
                        <span style={{ fontSize: '12px', color: 'var(--text3)' }}>
                          {b.bookingStatus === 'CANCELLED' ? '—' : `~₹${(bookingAmt * 0.9).toFixed(2)}`}
                        </span>
                      )}
                    </td>
                    <td><span className={`badge badge-${statusColor(b.bookingStatus)}`}>{b.bookingStatus}</span></td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Earnings note */}
      {bookings.length > 0 && (
        <div style={{ marginTop: '16px', padding: '12px 16px', background: '#f8fafc', border: '1px solid #e2e5f0', borderRadius: '10px', fontSize: '12px', color: '#64748b', display: 'flex', gap: '8px', alignItems: 'flex-start' }}>
          <span>ℹ️</span>
          <span>Your earning column shows the actual credited amount from wallet transactions. For bookings still in <strong>HOLD</strong> status, the estimated 90% is shown. Earnings are credited to your wallet <strong>immediately when a booking is confirmed</strong>. Check your Wallet page for the full transaction history.</span>
        </div>
      )}
    </div>
  );
}
